/* @autogenerated */
import { TenantRepository } from 'app/features/identity/tenant/repository/tenant-repository.service';
import { normalizeHeader } from 'app/shared/toolkit/entity-import/column-match';
import { TemplateRepository } from 'app/features/template/template/repository/template-repository.service';
import { take, map } from 'rxjs';
import { TemplateAsset } from 'app/features/template/template-asset/model/template-asset.model';
import {
  TEMPLATE_ASSET_EXCEL_COLUMNS,
  TEMPLATE_ASSET_EXCEL_SENSITIVE,
} from 'app/features/template/template-asset/model/template-asset-excel-columns';
import { BaseImportAction } from 'app/shared/toolkit/action/base-import-action';
import { TemplateAssetRepository } from 'app/features/template/template-asset/repository/template-asset-repository.service';
import { ImportDefinition } from 'app/shared/toolkit/entity-import/entity-import.model';
import { Component, inject } from '@angular/core';

/** Candidatos que pide cada búsqueda: el filtro puede no ser exacto y se comprueba aquí. */
const LOOKUP_LIMIT = 50;

@Component({
  selector: 'template-asset-view-import-action',
  standalone: false,
  templateUrl: './template-asset-view-import-action.component.html',
})
export class TemplateAssetViewImportActionComponent extends BaseImportAction<TemplateAsset> {
  protected readonly scope = 'template/template-asset';
  protected readonly repository = inject(TemplateAssetRepository);
  private readonly templateRepository = inject(TemplateRepository);
  private readonly tenantRepository = inject(TenantRepository);

  readonly definition: ImportDefinition<TemplateAsset> = {
    storageKey: 'template.template-asset',
    scope: this.scope,
    // Clave natural (índice único del modelo): una fila con los mismos valores actualiza el elemento
    keys: ['code', 'template', 'tenant'],
    columns: TEMPLATE_ASSET_EXCEL_COLUMNS,
    sensitive: TEMPLATE_ASSET_EXCEL_SENSITIVE,
    // Campos que el backend solo cambia con sus acciones: se aplican tras crear o actualizar
    actions: {
      enabled: [
        { name: 'enable', value: true, run: (item) => this.repository.enable(item.uid) },
        { name: 'disable', value: false, run: (item) => this.repository.disable(item.uid) },
      ],
    },
    references: {
      template: {
        resolve: (text) =>
          this.templateRepository.values({ search: text, limit: LOOKUP_LIMIT }).pipe(
            take(1),
            map((found) => {
              const wanted = normalizeHeader(text);
              const one = found.find(
                (candidate) => candidate.uid === text || normalizeHeader(candidate.code) === wanted,
              );
              return one ? { $ref: one.uid } : null;
            }),
          ),
      },
      tenant: {
        resolve: (text) =>
          this.tenantRepository.values({ search: text, limit: LOOKUP_LIMIT }).pipe(
            take(1),
            map((found) => {
              const wanted = normalizeHeader(text);
              const one = found.find(
                (candidate) => candidate.uid === text || normalizeHeader(candidate.name) === wanted,
              );
              return one ? { $ref: one.uid } : null;
            }),
          ),
      },
    },
    defaults: () => ({ enabled: true }),
    display: (values) => String(values.code ?? ''),
    target: {
      acl: () => this.repository.checkAcl(),
      find: (values) =>
        this.repository
          .values({
            code: values.code,
            template: values.template?.$ref ? [values.template.$ref] : undefined,
            tenant: values.tenant?.$ref ? [values.tenant.$ref] : undefined,
            limit: LOOKUP_LIMIT,
          })
          .pipe(
            take(1),
            map((found) =>
              found.filter(
                (item) =>
                  item.code === values.code &&
                  (!values.template?.$ref || item.template?.$ref === values.template.$ref) &&
                  (!values.tenant?.$ref || item.tenant?.$ref === values.tenant.$ref),
              ),
            ),
          ),
      add: (item) => this.repository.add(item),
      update: (item) => this.repository.update(item),
    },
  };
}
